void emit_try_catch_finally(J, js_Ast *trystm, js_Ast *catchvar, js_Ast *catchstm, js_Ast *finallystm) {
    int label_try = emit_jump_label(J);
    int label_catch = emit_jump_label(J);
    int label_finally = emit_jump_label(J);
    int label_end = emit_jump_label(J);

    emit_jump(J, label_try);
    emit_label(J, label_try);

    // Emit try block
    emit_statement(J, trystm);

    // Jump to finally on normal exit
    emit_jump(J, label_finally);

    // Emit catch block
    emit_label(J, label_catch);

    // Emit strict mode violation check for catchvar
    if (is_strict_mode(J)) {
        emit_strict_mode_check(J, catchvar);
    }

    // Assign exception to catchvar
    emit_assign(J, catchvar, get_exception(J));

    // Execute catchstm
    emit_statement(J, catchstm);

    // Rethrow if necessary
    emit_rethrow(J);

    emit_jump(J, label_finally);

    // Emit finally block
    emit_label(J, label_finally);
    emit_statement(J, finallystm);
    emit_jump(J, label_end);

    emit_label(J, label_end);
}

void js_EmitTryCatchFinally(js_Context *J, js_Ast *trystm, js_Ast *catchvar, js_Ast *catchstm, js_Ast *finallystm) {
    int tryLabel = js_NewLabel(J);
    int catchLabel = js_NewLabel(J);
    int finallyLabel = js_NewLabel(J);
    int endLabel = js_NewLabel(J);

    js_EmitJump(J, tryLabel);
    js_EmitLabel(J, tryLabel);
    js_EmitTry(J);

    js_EmitStatements(J, trystm);
    js_EmitJump(J, finallyLabel);

    js_EmitLabel(J, catchLabel);
    js_EmitCatch(J, catchvar);

    if (J->strictMode && js_IsThisUsed(catchvar)) {
        js_Error(J, "Catch variable may not be named 'this' in strict mode");
    }

    js_EmitStatements(J, catchstm);
    js_EmitRethrow(J);

    js_EmitLabel(J, finallyLabel);
    js_EmitFinally(J);
    js_EmitStatements(J, finallystm);
    js_EmitJump(J, endLabel);

    js_EmitLabel(J, endLabel);
}

